WITH latest_stage_snapshots AS (SELECT * FROM scores.stage_snapshots WHERE snapshot_date = (SELECT MAX(snapshot_date) FROM scores.stage_snapshots)),
joined_data AS (SELECT h.symbol, h.qty, h.avg_cost, s.stage, s.trading_signal FROM portfolio.holdings h JOIN latest_stage_snapshots s ON h.symbol = s.symbol)
SELECT symbol, qty, avg_cost, stage, trading_signal FROM joined_data WHERE trading_signal IN ('BUY', 'STRONG_BUY') OR stage = 'STAGE_2';

